// ---- Completion backlog ----
const pendingNudges = new Map<string, { record: AgentRecord; partial: boolean; grouped: boolean }>();
const pendingWorkflowNudges = new Map<string, () => { customType: string; content: string; display: boolean; details: CompletionDetails }>();
const NUDGE_HOLD_MS = 200;
const QUEUE_WAIT_POLL_MS = Math.floor(NUDGE_HOLD_MS / 4);
let nudgeTimer: ReturnType<typeof setTimeout> | undefined;
let notificationsClosed = false;

type CompletionDetails = NotificationDetails & { completionKey?: string };
function completionKey(record: AgentRecord): string {
  return `${record.startedAt}:${record.completedAt}`;
}

function acknowledgeNudges(ctx: ExtensionContext) {
  if (pendingNudges.size === 0 && pendingWorkflowNudges.size === 0) return;
  for (const entry of ctx.sessionManager.getBranch()) {
    if (entry.type !== "custom_message" || entry.customType !== "subagent-notification") continue;
    const details = entry.details as CompletionDetails | undefined;
    for (const detail of details ? [details, ...(details.others ?? [])] : []) {
      const pending = pendingNudges.get(detail.id);
      if (pending && (detail as CompletionDetails).completionKey === completionKey(pending.record)) {
        pendingNudges.delete(detail.id);
      }
      const workflow = pendingWorkflowNudges.get(detail.id);
      if (workflow && (detail as CompletionDetails).completionKey === workflow().details.completionKey) pendingWorkflowNudges.delete(detail.id);
    }
  }
}

function pendingNotification(ctx: ExtensionContext) {
  acknowledgeNudges(ctx);
  for (const [id, pending] of pendingNudges) {
    if (pending.record.resultConsumed || pending.record.completedAt == null) pendingNudges.delete(id);
  }
  const pending = [...pendingNudges.values()];
  const workflows = [...pendingWorkflowNudges.values()].map(build => build());
  if (pending.length === 0) {
    if (workflows.length === 0) return undefined;
    const [first, ...rest] = workflows;
    return { ...first, content: workflows.map(item => item.content).join('\n\n'),
      details: { ...first.details, ...(rest.length ? { others: rest.map(item => item.details) } : {}) } };
  }
  const records = pending.map(item => item.record);
  const grouped = records.length > 1 || pending.some(item => item.grouped);
  const maxLen = grouped ? 300 : 500;
  const detailsFor = (record: AgentRecord): CompletionDetails => ({
    ...buildNotificationDetails(record, maxLen, agentActivity.get(record.id)),
    completionKey: completionKey(record),
  });
  const details = detailsFor(records[0]);
  if (records.length > 1) details.others = records.slice(1).map(detailsFor);
  const body = records.map(record => formatTaskNotification(record, maxLen, showCost)).join('\n\n');
  const content = !grouped
    ? body + (records[0].outputFile ? `\nFull transcript available at: ${records[0].outputFile}` : '')
    : `Background agent group completed: ${records.length} agent(s) finished${pending.some(item => item.partial) ? ' (includes partial group)' : ''}\n\n${body}\n\nUse get_subagent_result for full output.`;
  if (workflows.length) details.others = [...(details.others ?? []), ...workflows.map(item => item.details)];
  return { customType: "subagent-notification", content: [content, ...workflows.map(item => item.content)].join('\n\n'), display: true, details };
}

function armIdleNudge() {
  if (notificationsClosed || nudgeTimer != null || (pendingNudges.size === 0 && pendingWorkflowNudges.size === 0)) return;
  nudgeTimer = setTimeout(() => {
    nudgeTimer = undefined;
    try {
      const ctx = currentCtx;
      if (notificationsClosed || !ctx || !ctx.isIdle()) return;
      const notification = pendingNotification(ctx);
      if (!notification) return;
      pi.sendMessage<NotificationDetails>(notification, { deliverAs: "followUp", triggerTurn: true });
      acknowledgeNudges(ctx);
    } catch { /* retain unread results for the next actionable boundary */ }
  }, NUDGE_HOLD_MS);
}

function queueNudges(records: AgentRecord[], partial = false, grouped = false) {
  if (notificationsClosed) return;
  for (const record of records) {
    if (!record.resultConsumed && record.completedAt != null) pendingNudges.set(record.id, { record, partial, grouped });
  }
  armIdleNudge();
}

function cancelNudge(key: string) {
  pendingNudges.delete(key);
  pendingWorkflowNudges.delete(key);
}

function clearNudges() {
  if (nudgeTimer != null) clearTimeout(nudgeTimer);
  nudgeTimer = undefined;
  pendingNudges.clear();
  pendingWorkflowNudges.clear();
}

// Pi 0.87.1 owns actionable boundaries; upstream's 0.84.2 types do not declare them.
type CompletionBoundary = { entries: unknown[]; outcome: "completed" | "aborted" | "error" };
type CompletionBoundaryRegistration = (
  event: "turn_end" | "agent_before_settle",
  handler: (event: CompletionBoundary, ctx: ExtensionContext) => { entries: unknown[]; continue: boolean } | undefined,
) => void;
const registerCompletionBoundary = pi.on as unknown as CompletionBoundaryRegistration;
function flushCompletionBoundary(event: CompletionBoundary, ctx: ExtensionContext) {
  if (notificationsClosed || !Array.isArray(event.entries) || event.outcome !== "completed") return;
  if (batchFinalizeTimer != null) {
    clearTimeout(batchFinalizeTimer);
    finalizeBatch();
  }
  const notification = pendingNotification(ctx);
  if (!notification) return;
  // A later handler can replace drafts; forget only notifications committed to the branch.
  return { entries: [...event.entries, { type: "custom_message", ...notification }], continue: true };
}
registerCompletionBoundary("turn_end", flushCompletionBoundary);
registerCompletionBoundary("agent_before_settle", flushCompletionBoundary);
(pi.on as unknown as (event: "agent_settled", handler: () => void) => void)("agent_settled", armIdleNudge);

// ---- Individual nudge helper (async join mode) ----
function sendIndividualNudge(record: AgentRecord) {
  agentActivity.delete(record.id);
  widget.markFinished(record.id);
  fleet.onAgentFinished(record.id);
  queueNudges([record]);
  widget.update();
}

